<template>
  <div class="home-container">
    <div class="header">
      <h1>🌡️ Моніторинг Клімату</h1>
      <button @click="fetchData" :disabled="loading" class="refresh-btn">
        {{ loading ? 'Завантаження...' : 'Оновити дані' }}
      </button>
    </div>

    <!-- Блок помилки -->
    <div v-if="error" class="error-banner">
      {{ error }}
    </div>

    <!-- Головна панель (Останні показники) -->
    <div v-if="latestMeasurement" class="dashboard-grid">
      <div class="card temp-card">
        <div class="card-title">Температура</div>
        <div class="card-value">{{ formatNumber(latestMeasurement.temperature) }}°C</div>
        <div class="card-sub">Останнє оновлення</div>
      </div>

      <div class="card hum-card">
        <div class="card-title">Вологість</div>
        <div class="card-value">{{ formatNumber(latestMeasurement.humidity) }}%</div>
        <div class="card-sub">Стан повітря</div>
      </div>

      <div class="card info-card">
        <div class="card-title">Інфо станції</div>
        <div class="info-row">
          <span>ID:</span> <strong>{{ latestMeasurement.station_id }}</strong>
        </div>
        <div class="info-row">
          <span>Час:</span> <strong>{{ formatTime(latestMeasurement.timestamp) }}</strong>
        </div>
        <div class="info-row">
          <span>Коорд:</span> 
          <a 
            :href="`https://www.google.com/maps/search/?api=1&query=${latestMeasurement.lat},${latestMeasurement.lng}`" 
            target="_blank"
            class="map-link"
          >
            {{ latestMeasurement.lat }}, {{ latestMeasurement.lng }}
          </a>
        </div>
      </div>
    </div>

    <!-- Таблиця історії -->
    <div class="history-section">
      <h2>Історія вимірювань</h2>
      <div class="table-responsive">
        <table>
          <thead>
            <tr>
              <th>Час</th>
              <th>Температура</th>
              <th>Вологість</th>
              <th>ID Станції</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="item in sortedMeasurements" :key="item.id">
              <td>{{ formatFullDate(item.timestamp) }}</td>
              <td :class="getTempClass(item.temperature)">
                {{ formatNumber(item.temperature) }}°C
              </td>
              <td>{{ formatNumber(item.humidity) }}%</td>
              <td>{{ item.station_id }}</td>
            </tr>
            <tr v-if="measurements.length === 0 && !loading">
              <td colspan="4" class="empty-state">Дані відсутні</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'HomeView',
  data() {
    return {
      measurements: [],
      loading: false,
      error: null,
      apiUrl: "https://home-server-9e586-default-rtdb.firebaseio.com/measurements.json?auth=eOpdxQjllRN3hJ2Z9bIag33HIC2LaU97GkyBRvXG"
    };
  },
  computed: {
    // Сортуємо: нові зверху
    sortedMeasurements() {
      return [...this.measurements].sort((a, b) => {
        return new Date(b.timestamp) - new Date(a.timestamp);
      });
    },
    // Беремо найперший елемент після сортування
    latestMeasurement() {
      if (this.sortedMeasurements.length > 0) {
        return this.sortedMeasurements[0];
      }
      return null;
    }
  },
  methods: {
    async fetchData() {
      this.loading = true;
      this.error = null;
      try {
        const response = await fetch(this.apiUrl);
        if (!response.ok) {
          throw new Error(`HTTP помилка! статус: ${response.status}`);
        }
        const data = await response.json();
        
        // Перетворення об'єкта Firebase (ключ-значення) в масив
        if (data) {
          this.measurements = Object.keys(data).map(key => ({
            id: key,
            ...data[key]
          }));
        } else {
          this.measurements = [];
        }
      } catch (err) {
        this.error = "Не вдалося завантажити дані: " + err.message;
        console.error(err);
      } finally {
        this.loading = false;
      }
    },
    formatNumber(val) {
      if (val === undefined || val === null || val === "") return "--";
      return parseFloat(val).toFixed(1);
    },
    formatTime(isoString) {
      if (!isoString) return "--:--";
      const date = new Date(isoString);
      return date.toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit' });
    },
    formatFullDate(isoString) {
      if (!isoString) return "Невідомо";
      const date = new Date(isoString);
      return date.toLocaleString('uk-UA');
    },
    getTempClass(temp) {
      const t = parseFloat(temp);
      if (t < 10) return 'text-cold';
      if (t > 28) return 'text-hot';
      return 'text-normal';
    }
  },
  mounted() {
    this.fetchData();
    // Оновлювати кожні 60 секунд автоматично
    setInterval(this.fetchData, 60000);
  }
};
</script>

